type Messages = typeof messages.en;
type I18nContextValue = { locale: Locale; setLocale: (locale: Locale) => Promise<void>; t: <K extends keyof Messages>(key: K, ...args: Messages[K] extends (...args: infer P) => string ? P : []) => string };
const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale);
  useEffect(() => { void AsyncStorage.getItem(STORAGE_KEY).then((value) => { if (value === 'en' || value === 'fr' || value === 'it') setLocaleState(value); }); }, []);
  const value = useMemo<I18nContextValue>(() => ({
    locale,
    setLocale: async (next) => { setLocaleState(next); await AsyncStorage.setItem(STORAGE_KEY, next); },
    t: (key, ...args) => {
      const value = messages[locale][key] as unknown;
      return typeof value === 'function' ? (value as (...params: unknown[]) => string)(...args) : String(value);
    },
  }), [locale]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}
export function useI18n() { const value = useContext(I18nContext); if (!value) throw new Error('useI18n must be used within I18nProvider'); return value; }
